class SharedForwardTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.threads = torch.get_num_threads()
        torch.set_num_threads(1)

    @classmethod
    def tearDownClass(cls):
        torch.set_num_threads(cls.threads)

    def test_single_executor_preserves_pre_refactor_periodic_energy_and_force(self):
        for (has_line, angular), (energy, forces) in _LEGACY_EF.items():
            with self.subTest(has_line=has_line, angular=angular):
                model = toy_model(smoothed=True, reference=None, angular=angular,
                                  dtype=torch.float64)
                _, graph = frozen_fixture(has_line=has_line, periodic=True,
                                          dtype=torch.float64)
                expected_e = torch.tensor(energy, dtype=torch.float64)
                expected_f = torch.tensor(forces, dtype=torch.float64)
                single = model([graph], task="ef")
                # The original goldens stay unchanged. PyTorch 2.8 produces
                # 7.48e-9..8.23e-9 energy drift in BOTH MD and FastMD on this
                # seeded fixture; its force drift is 1.54e-9..4.87e-9.
                # Allow 1e-8 absolute drift only against these fixed goldens.
                # Training VJPs and independent stage/VJP checks stay strict.
                torch.testing.assert_close(single["e"][0], expected_e, atol=1e-8, rtol=2e-9)
                torch.testing.assert_close(single["f"][0], expected_f, atol=1e-8, rtol=2e-9)
                # Dead edge updates (MATRIS_SKIP_DEAD_THREEBODY_TAIL, default on): under the conservative
                # head the last block's bond update, and without triplets every atom attention's bond
                # update, are skipped; E/F/S are bitwise those of the full computation.
                dead = {}
                for skip in (True, False):
                    ffn_calls = []
                    hooks = [block.refine_block_atom_graph.edge_FFN.register_forward_hook(
                        lambda *args: ffn_calls.append(1)) for block in model.interaction_block]
                    try:
                        with patch.object(interaction_block, "_SKIP_DEAD_THREEBODY_TAIL", skip), \
                                patch.object(interaction_block.Graph_Attention_Layer, "attention_edges", autospec=True,
                                             side_effect=interaction_block.Graph_Attention_Layer.attention_edges) as edges:
                            dead[skip] = (model([graph], task="efs"), len(ffn_calls), edges.call_count)
                    finally:
                        for hook in hooks:
                            hook.remove()
                blocks = len(model.interaction_block)
                self.assertEqual(dead[False][1:], (blocks, 2 * blocks if has_line else blocks))
                self.assertEqual(dead[True][1:], (blocks - 1, 2 * blocks if has_line else 0))
                for key in ("e", "f", "s"):
                    self.assertTrue(torch.equal(dead[True][0][key][0], dead[False][0][key][0]), key)

    def test_single_training_checkpoint_preserves_force_loss_parameter_gradients(self):
        """Exercise second derivatives, not merely a frozen-weight E/F call."""
        for has_line in (False, True):
            for smoothed in (False, True):
                with self.subTest(has_line=has_line, smoothed=smoothed):
                    plain = toy_model(smoothed=smoothed, reference=None,
                                      dtype=torch.float64).train().requires_grad_(True)
                    checked = deepcopy(plain)
                    checked.enable_checkpoint = True
                    for block in checked.interaction_block:
                        block.enable_checkpoint = True
                    predictions = []
                    for model in (plain, checked):
                        _, graph = frozen_fixture(has_line=has_line, periodic=True,
                                                  dtype=torch.float64)
                        prediction = model([graph], task="efs", is_training=True)
                        loss = (prediction["e"].square().sum()
                                + prediction["f"][0].square().sum() / 7
                                + prediction["s"][0].square().sum() / 11)
                        loss.backward()
                        predictions.append(prediction)
                    for key in ("e", "f", "s"):
                        torch.testing.assert_close(predictions[0][key][0], predictions[1][key][0],
                                                   atol=2e-11, rtol=2e-10)
                    self.assertEqual(tuple(plain.state_dict()), tuple(checked.state_dict()))
                    seen = 0
                    for (name, first), (other_name, second) in zip(
                            plain.named_parameters(), checked.named_parameters()):
                        self.assertEqual(name, other_name)
                        with self.subTest(parameter=name):
                            if first.grad is None:
                                self.assertIsNone(second.grad)
                            else:
                                self.assertIsNotNone(second.grad)
                                self.assertTrue(torch.isfinite(first.grad).all())
                                torch.testing.assert_close(first.grad, second.grad,
                                                           atol=2e-10, rtol=2e-9)
                                seen += 1
                    self.assertGreater(seen, 20)

    def test_unsorted_directed_pair_rows_preserve_outputs_and_all_input_vjps(self):
        """Pair identity is a mapping, not the adjacency of two local rows."""
        permutation = torch.tensor([4, 1, 2, 5, 0, 3])
        target = torch.tensor([0, 1, 0, 2, 2, 3])
        source = torch.tensor([1, 0, 2, 0, 3, 2])
        d2u = torch.tensor([0, 0, 1, 1, 2, 2])
        for smoothed in (False, True):
            model = toy_model(smoothed=smoothed, reference=None, dtype=torch.float64)
            block = model.interaction_block[0]
            for kind in ("attention", "refinement"):
                with self.subTest(smoothed=smoothed, kind=kind):
                    layer = (block.attn_block_atom_graph if kind == "attention"
                             else block.refine_block_atom_graph)
                    values = (torch.randn(4, 6, dtype=torch.float64),
                              torch.randn(3, 6, dtype=torch.float64),
                              torch.randn(3, 3, dtype=torch.float64))
                    outputs, inputs = [], []
                    for order in (torch.arange(6), permutation):
                        node, edge, basis = [value.clone().requires_grad_(True) for value in values]
                        graph = {"source_index": source[order], "target_index": target[order],
                                 "source_bincount": torch.bincount(source, minlength=4).clamp_min(1),
                                 "target_bincount": torch.bincount(target, minlength=4).clamp_min(1),
                                 "num_undirected": 3, "_ops": hand_built_dispatcher()}
                        if kind == "attention":
                            output = layer(node, edge, graph, directed2undirected=d2u[order])
                        else:
                            output = layer(node, edge, basis, graph, directed2undirected=d2u[order])
                        outputs.append(output)
                        inputs.append((node, edge, basis))
                    cotangents = tuple(torch.randn_like(value) for value in outputs[0])
                    for expected, actual in zip(*outputs):
                        torch.testing.assert_close(actual, expected, atol=2e-12, rtol=2e-11)
                    gradients = [torch.autograd.grad(output, arguments, cotangents, allow_unused=True)
                                 for output, arguments in zip(outputs, inputs)]
                    for expected, actual in zip(*gradients):
                        if expected is None:
                            self.assertIsNone(actual)
                        else:
                            torch.testing.assert_close(actual, expected, atol=2e-12, rtol=2e-11)


if __name__ == "__main__":
    unittest.main()
